<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\Relations\BelongsTo;use Illuminate\Database\Eloquent\Relations\HasMany;use Illuminate\Support\Str;
class BackupSchedule extends Model{protected $fillable=['tenant_id','application_deployment_id','backup_destination_id','uuid','name','backup_type','frequency','cron_expression','keep_last','delete_after_days','enabled','last_run_at','next_run_at'];protected static function booted():void{static::creating(fn($m)=>$m->uuid??=(string)Str::uuid());}protected function casts():array{return['enabled'=>'boolean','last_run_at'=>'datetime','next_run_at'=>'datetime'];}public function deployment():BelongsTo{return $this->belongsTo(ApplicationDeployment::class,'application_deployment_id')->withTrashed();}public function destination():BelongsTo{return $this->belongsTo(BackupDestination::class,'backup_destination_id');}public function backups():HasMany{return $this->hasMany(Backup::class);}public function frequencyLabel():string{return ucfirst($this->frequency);}public function retentionLabel():string{return match($this->frequency){'hourly'=>$this->keep_last.' hours','daily'=>$this->keep_last.' days','weekly'=>$this->keep_last.' weeks',default=>$this->keep_last.' kept'};}public function applicationName():string{return $this->deployment?->application?->name??$this->deployment?->name??'—';}}
